package com.ruoyi.metal.service;
import java.math.*;import java.util.*;import com.alibaba.fastjson2.JSON;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.*;
import com.ruoyi.metal.security.FactoryScope;import com.ruoyi.common.exception.ServiceException;
/** Whole-order boundary ledger, derived exclusively from independently posted business facts. */
@Service
@Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
public class WorkOrderWeightBalanceService {
 public static String label(String key){return switch(key){case "RAW_ISSUED"->"原料领入";case "EXTERNAL_SEMI_ISSUED"->"外部半成品领入";case "SEMI_ADJUSTMENT"->"来源半成品库存净调整";case "INPUT"->"新增投入合计";case "FINISHED_OUTPUT"->"成品累计产出";case "OWN_SEMI_STOCK"->"本单半成品在库";case "CROSS_SEMI_OUT"->"半成品跨单净转出";case "OTHER_SEMI_OUT"->"其他半成品净出库";case "SETTLED_LOSS"->"已结算损耗";case "PROCESS_RAW_RETURN"->"加工余料净还库";case "PROCESS_RAW_RETURN_GROSS"->"加工余料累计回收";case "INTERNAL_RECOVERED_RAW"->"回收原料本单净再领用（仅追溯）";case "RAW_RETURN"->"原料还库";case "EXTERNAL_SEMI_RETURN"->"外部半成品还库";case "OPEN_DIFFERENCE"->"未结算在制差额（含待确认损耗）";case "RECONCILIATION_DIFFERENCE"->"核对差额";case "INTERNAL_SEMI"->"内部半成品流转（不计新增投入）";default->key;};}
 private final JdbcTemplate jdbc;private final FactoryScope scope;
 public WorkOrderWeightBalanceService(JdbcTemplate j,FactoryScope s){jdbc=j;scope=s;}
 static BigDecimal difference(BigDecimal input,List<BigDecimal> outputs){for(var v:outputs)input=input.subtract(v);return input.setScale(6,RoundingMode.UNNECESSARY);}
 private static BigDecimal d(Object v){return SemiFlowService.dec(v);}private static long n(Object v){return SemiFlowService.num(v);}
 public Map<String,Object> summary(long work,Long item){return calculate(work,item);}
 private Map<String,Object> calculate(long work,Long item){
  var w=jdbc.queryForMap("SELECT work_order_id,order_no,factory_id,status,version FROM metal_work_order WHERE work_order_id=? AND del_flag='0'",work);scope.check(n(w.get("factory_id")));
  var items=jdbc.queryForList("SELECT item_id,product_snapshot,quantity FROM metal_work_order_item WHERE work_order_id=? ORDER BY item_id",work);if(item!=null&&items.stream().noneMatch(r->n(r.get("item_id"))==item))throw new ServiceException("产品明细不属于当前工单",403);
  // Includes consumption/return by other orders of this order's origin stock.
  var facts=jdbc.queryForList("WITH relevant_lines AS (SELECT l.line_id FROM metal_warehouse_order o JOIN metal_warehouse_order_line l ON l.order_id=o.order_id WHERE o.work_order_id=? UNION SELECT l.line_id FROM metal_process_batch b JOIN metal_inventory i ON i.origin_batch_id=b.batch_id JOIN metal_warehouse_order_line l ON l.inventory_id=i.inventory_id WHERE b.work_order_id=?) SELECT l.*,o.order_no,o.type,o.status order_status,o.work_order_id target_work,o.batch_id target_batch,o.version order_version,b.item_id target_item,b.status batch_status,b.sequence_no,sb.work_order_id origin_work,sb.item_id origin_item,i.origin_batch_id,rb.work_order_id recovery_work,rb.item_id recovery_item FROM relevant_lines selected JOIN metal_warehouse_order_line l ON l.line_id=selected.line_id JOIN metal_warehouse_order o ON o.order_id=l.order_id JOIN metal_inventory i ON i.inventory_id=l.inventory_id LEFT JOIN metal_process_batch b ON b.batch_id=o.batch_id LEFT JOIN metal_process_batch sb ON sb.batch_id=i.origin_batch_id LEFT JOIN metal_process_raw_return_line rr ON rr.inventory_id=i.inventory_id LEFT JOIN metal_process_batch rb ON rb.batch_id=rr.batch_id ORDER BY o.order_id,l.line_id",work,work);
  var stocks=jdbc.queryForList("SELECT i.*,b.item_id,b.status batch_status FROM metal_inventory i JOIN metal_process_batch b ON b.batch_id=i.origin_batch_id WHERE b.work_order_id=? AND i.category='SEMI' ORDER BY i.inventory_id",work);
  var reports=jdbc.queryForList("SELECT b.*,r.report_id,r.loss_weight,r.issued_weight,r.returned_weight,r.completed_quantity report_quantity,r.voided FROM metal_process_batch b LEFT JOIN metal_work_report r ON r.batch_id=b.batch_id WHERE b.work_order_id=? ORDER BY b.batch_id",work);
  var totals=new LinkedHashMap<String,BigDecimal>();for(String k:List.of("RAW_ISSUED","EXTERNAL_SEMI_ISSUED","SEMI_ADJUSTMENT","FINISHED_OUTPUT","OWN_SEMI_STOCK","CROSS_SEMI_OUT","OTHER_SEMI_OUT","SETTLED_LOSS","RAW_RETURN","EXTERNAL_SEMI_RETURN","OPEN_DIFFERENCE","INTERNAL_SEMI","PROCESS_RAW_RETURN","PROCESS_RAW_RETURN_GROSS","INTERNAL_RECOVERED_RAW"))totals.put(k,BigDecimal.ZERO);
  var lines=new ArrayList<Map<String,Object>>();var anomalies=new ArrayList<String>();var batchWeights=new HashMap<Long,BigDecimal[]>();
  for(var f:facts){if(!"POSTED".equals(f.get("order_status")))continue;long target=n(f.get("target_work")),origin=n(f.get("origin_work"));boolean targetHere=target==work&&(item==null||n(f.get("target_item"))==item),originHere=origin==work&&(item==null||n(f.get("origin_item"))==item);String type=String.valueOf(f.get("type")),category=String.valueOf(f.get("category"));BigDecimal weight=d(f.get("net_weight"));String key=null;BigDecimal signed=weight;
   if(targetHere){var b=batchWeights.computeIfAbsent(n(f.get("target_batch")),x->new BigDecimal[]{BigDecimal.ZERO,BigDecimal.ZERO});if(type.equals("PRODUCTION_OUT"))b[0]=b[0].add(weight);if(Set.of("RAW_RETURN","SEMI_RETURN","PROCESS_RAW_RETURN","SEMI_IN","FINISHED_IN").contains(type))b[1]=b[1].add(weight);
    boolean internalRecovery=n(f.get("recovery_work"))==work&&(item==null||n(f.get("recovery_item"))==item);
    if(type.equals("PRODUCTION_OUT")){if(category.equals("RAW")){key=internalRecovery?"PROCESS_RAW_RETURN":"RAW_ISSUED";if(internalRecovery)signed=weight.negate();}else if(category.equals("SEMI")){if(origin==0)anomalies.add("来源不完整："+f.get("order_no")+" / "+f.get("line_id"));else key=origin==work?"INTERNAL_SEMI":"EXTERNAL_SEMI_ISSUED";}}
    else if(type.equals("FINISHED_IN"))key="FINISHED_OUTPUT";else if(type.equals("RAW_RETURN"))key=internalRecovery?"PROCESS_RAW_RETURN":"RAW_RETURN";else if(type.equals("PROCESS_RAW_RETURN")){key="PROCESS_RAW_RETURN";totals.put("PROCESS_RAW_RETURN_GROSS",totals.get("PROCESS_RAW_RETURN_GROSS").add(weight));var gross=new LinkedHashMap<String,Object>();gross.put("category","PROCESS_RAW_RETURN_GROSS");gross.put("orderNo",f.get("order_no"));gross.put("lineId",f.get("line_id").toString());gross.put("weight",weight.setScale(6).toPlainString());gross.put("name",f.get("name"));gross.put("code",f.get("code"));lines.add(gross);}else if(type.equals("SEMI_RETURN")){if(origin==0)anomalies.add("还库来源不完整："+f.get("order_no"));else key=origin==work?"INTERNAL_SEMI":"EXTERNAL_SEMI_RETURN";}
   }
   if(originHere){if(type.equals("PRODUCTION_OUT")&&target!=work)key="CROSS_SEMI_OUT";else if(type.equals("SEMI_RETURN")&&target!=work){key="CROSS_SEMI_OUT";signed=weight.negate();}else if(type.equals("SEMI_OUT"))key="OTHER_SEMI_OUT";else if(type.equals("ADJUST")&&category.equals("SEMI"))key="SEMI_ADJUSTMENT";}
   if(targetHere&&"PROCESS_RAW_RETURN".equals(key)&&!type.equals("PROCESS_RAW_RETURN")){
    BigDecimal net=signed.negate();totals.put("INTERNAL_RECOVERED_RAW",totals.get("INTERNAL_RECOVERED_RAW").add(net));var internal=new LinkedHashMap<String,Object>();internal.put("category","INTERNAL_RECOVERED_RAW");internal.put("orderNo",f.get("order_no"));internal.put("lineId",f.get("line_id").toString());internal.put("weight",net.setScale(6).toPlainString());internal.put("name",f.get("name"));internal.put("code",f.get("code"));lines.add(internal);
   }
   if(key!=null){totals.put(key,totals.get(key).add(signed));var row=new LinkedHashMap<String,Object>();row.put("category",key);row.put("orderNo",f.get("order_no"));row.put("orderId",String.valueOf(f.get("order_id")));row.put("lineId",String.valueOf(f.get("line_id")));row.put("batchId",f.get("target_batch")==null?null:String.valueOf(f.get("target_batch")));row.put("name",f.get("name"));row.put("code",f.get("code"));row.put("weight",signed.setScale(6).toPlainString());row.put("quantity",f.get("quantity"));row.put("itemId",String.valueOf(targetHere?f.get("target_item"):f.get("origin_item")));lines.add(row);}
  }
  for(var stock:stocks){if(item!=null&&n(stock.get("item_id"))!=item)continue;BigDecimal weight=d(stock.get("net_weight"));totals.put("OWN_SEMI_STOCK",totals.get("OWN_SEMI_STOCK").add(weight));if(!"NORMAL".equals(stock.get("ownership_status"))||weight.signum()<0||(n(stock.get("quantity"))==0)!=(weight.signum()==0))anomalies.add("库存待核对："+stock.get("inventory_id"));var r=new LinkedHashMap<String,Object>();r.put("category","OWN_SEMI_STOCK");r.put("lineId","stock:"+stock.get("inventory_id"));r.put("orderNo",stock.get("batch_no"));r.put("name",stock.get("name"));r.put("itemId",String.valueOf(stock.get("item_id")));r.put("weight",weight.setScale(6).toPlainString());lines.add(r);}
  for(var b:reports){if(item!=null&&n(b.get("item_id"))!=item||"VOID".equals(b.get("status")))continue;var bw=batchWeights.getOrDefault(n(b.get("batch_id")),new BigDecimal[]{BigDecimal.ZERO,BigDecimal.ZERO});BigDecimal gap=bw[0].subtract(bw[1]);if(gap.signum()<0)anomalies.add("批次领料小于有效产出及还库："+b.get("batch_no"));String key="OPEN_DIFFERENCE";BigDecimal weight=gap;if("SETTLED".equals(b.get("status"))){key="SETTLED_LOSS";weight=d(b.get("loss_weight"));if(b.get("report_id")==null||Boolean.TRUE.equals(b.get("voided"))||gap.compareTo(weight)!=0||d(b.get("issued_weight")).compareTo(bw[0])!=0||d(b.get("returned_weight")).compareTo(bw[1])!=0||n(b.get("completed_quantity"))!=n(b.get("report_quantity")))anomalies.add("已结算报工与单据不一致："+b.get("batch_no"));}totals.put(key,totals.get(key).add(weight));var r=new LinkedHashMap<String,Object>();r.put("category",key);r.put("lineId","batch:"+b.get("batch_id"));r.put("batchId",String.valueOf(b.get("batch_id")));r.put("orderNo",b.get("batch_no"));r.put("itemId",String.valueOf(b.get("item_id")));r.put("weight",weight.setScale(6).toPlainString());lines.add(r);}
  BigDecimal input=totals.get("RAW_ISSUED").add(totals.get("EXTERNAL_SEMI_ISSUED")).add(totals.get("SEMI_ADJUSTMENT"));var output=new ArrayList<BigDecimal>();for(String k:List.of("FINISHED_OUTPUT","OWN_SEMI_STOCK","CROSS_SEMI_OUT","OTHER_SEMI_OUT","SETTLED_LOSS","RAW_RETURN","EXTERNAL_SEMI_RETURN","PROCESS_RAW_RETURN","OPEN_DIFFERENCE"))output.add(totals.get(k));BigDecimal diff=difference(input,output);var printable=new LinkedHashMap<String,String>();totals.forEach((k,v)->printable.put(k,v.setScale(6).toPlainString()));printable.put("INPUT",input.setScale(6).toPlainString());printable.put("RECONCILIATION_DIFFERENCE",diff.toPlainString());
  String token=SemiSourcePolicyService.hash(Arrays.asList(w,item,items,facts,stocks,reports));var result=new LinkedHashMap<String,Object>();result.put("workOrderNo",w.get("order_no"));result.put("totals",printable);result.put("snapshotToken",token);result.put("readTime",java.time.LocalDateTime.now().toString());result.put("status",!anomalies.isEmpty()?"INCOMPLETE":diff.signum()==0?"BALANCED":"REVIEW");result.put("anomalies",anomalies);result.put("items",items);result.put("lines",lines);return result;
 }
 public Map<String,Object> lines(long work,Long item,String category,int page,int size,String token){if(page<1||size<1||size>100)throw new ServiceException("分页范围不合法");var summary=calculate(work,item);if(token==null||!token.equals(summary.get("snapshotToken")))throw new ServiceException("总账已变化，请刷新后重试",409);var selected=((List<Map<String,Object>>)summary.get("lines")).stream().filter(r->category==null||category.equals(r.get("category"))).toList();return Map.of("rows",selected.stream().skip((long)(page-1)*size).limit(size).toList(),"total",selected.size(),"snapshotToken",token);}
 public Map<String,Object> export(long work,Long item,String token){var result=calculate(work,item);if(token==null||!token.equals(result.get("snapshotToken")))throw new ServiceException("总账已变化，请刷新后导出",409);return result;}
}
